/** La normalisation garde l'apostrophe : « l'addition » est un seul mot. On ajoute donc les formes élidées des mots français. */
const ELISIONS = ["l'", "d'", "j'", "qu'", "m'", "s'", "n'", "t'"];
const elide = (group: string[]): string[] => [...new Set(group.flatMap((word) => /^[aeiouyhàâéèêëîïôûœ]/i.test(word) && !word.includes(" ") ? [word, ...ELISIONS.map((e) => e + word)] : [word]))];

export const ES_PHRASE_SITUATIONS: PhraseSituation[] = SITUATION_DEFS.map(([id, title, topic, level]) => ({ id, title, topic, level }));

export const ES_PHRASES: PhraseItem[] = SITUATION_DEFS.flatMap(([situation]) =>
  (ROWS[situation] ?? []).map(([level, fr, targets, keys, frVariants, frKeys, note], index): PhraseItem => ({
    id: `es-ph-${situation}-${String(index + 1).padStart(3, "0")}`,
    situation, level, fr, targets, keys, frVariants, frKeys: frKeys.map(elide), note
  }))
);
